 labels={'senate2024special':('2024 same-seat Class II special / 17','Love (Democratic) vs Ricketts (Republican)'), 'senate2024regular':('2024 other-seat Class I regular / 16','Osborn (By Petition) vs Fischer (Republican)'), 'president2024':('2024 president statewide / 11–12','Harris/Walz (Democratic) vs Trump/Vance (Republican)'), 'governor2022':('2022 governor / 13–14','Blood/Davis (Democratic) vs Pillen/Kelly (Republican)'), 'senate2020':('2020 same-seat Senate / 16–17','Janicek (Democratic) vs Sasse (Republican)')}
 for key,(label,pair)in labels.items():
  tab=t[key];candidates='; '.join(f'{col.split("|")[0]} ({col.split("|")[1] or "generic scope"}) **{v:,}**'for col,v in zip(tab['columns'],tab['state']))
  report+=f'| {label} | {candidates} | {sum(tab["state"]):,} | {pair} | {sum(tab["state"][:2]):,} | +{own[key]["unbounded_shift_share_pp"]:.6f} pp |\n'
